 {'id': "PEDS-C27-048", 'sec': "Lung function abnormalities", 'page': 121, 'q': "A bronchodilator response in asthma is defined as FEV1 increasing by more than 15%.", 'opts': ["True", "False"], 'ans': 1, 'exp': "False — bronchodilator response: FEV1 ↑ by > 12% (> 15% is the fall on exercise challenge). (Book p121)", 'type': "tf"},
 {'type': "case", 'sec': "Lung function abnormalities", 'page': 121, 'stem': "A 9-year-old with recurrent nocturnal wheeze undergoes spirometry: FEV1 is reduced with an FEV1/FVC ratio of 0.7. After 400 mcg inhaled salbutamol, FEV1 improves by 15%. Peak flow records over 2 weeks vary by 25% between morning and evening readings.", 'q': "These lung function findings are —", 'opts': ["Suggestive of a fixed restrictive defect", "Diagnostic of bronchiolitis obliterans", "Normal for age with no abnormality", "Diagnostic of reversible airflow obstruction (asthma)"], 'ans': 3, 'exp': "FEV1 ↓ with FEV1/FVC < 0.8 = airflow limitation; post-bronchodilator FEV1 ↑ > 12% = bronchodilator response; AM-to-PM variation > 20% = diurnal variation → reversible airflow obstruction of asthma. (Book p121)", 'id': "PEDS-C27-049"},
 {'type': "odd", 'sec': "Lung function abnormalities", 'page': 121, 'q': "Odd one out (parameters used to demonstrate asthma):", 'opts': ["Fall in FEV1 by > 15% on exercise challenge", "Rise in FEV1 by > 12% after bronchodilator", "AM to PM variation in PEF by > 20%", "Rise in FEV1 by > 12% after nebulised saline"], 'ans': 3, 'exp': "Exercise fall > 15%, bronchodilator rise > 12% and diurnal variation > 20% are the described asthma parameters; SALINE is not a bronchodilator. (Book p121)", 'id': "PEDS-C27-050"},
